    const r = await BB.api(`/api/interviews?${BB.qs({ filter: f, page: q.page })}`);
    el.innerHTML = `<div class="filters">${['Upcoming', 'Result pending', 'Done', 'Cancelled / no-show', 'All'].map((x) => `<span class="chip ${f === x ? 'on' : ''}" data-fl="${x}">${x}</span>`).join('')}</div>
      <div class="card">${BB.table([{ t: 'ID', f: (i) => `<span class="mono">${i.id}</span>` }, { t: 'Time', f: (i) => fmtDT(i.at) }, { t: 'Candidate', f: (i) => `<b>${esc(i.candidate_name)}</b>` }, { t: 'Job', f: (i) => `${esc(i.job_title)}<div class="tiny muted">${esc(i.client_name)}</div>` }, { t: 'Round', f: (i) => `<span class="badge ${i.round === 'ours' ? 'b-primary' : 'b-violet'}">${i.round === 'ours' ? 'Ours' : 'Client'}</span>` }, { t: 'Interviewer', f: (i) => esc(i.interviewer || '—'), hideSm: 1 }, { t: 'Status', f: (i) => `<span class="badge ${i.view_status === 'Result pending' ? 'b-amber' : 'b-outline'}">${esc(i.view_status)}</span>${i.confirmed ? ' <span class="badge b-green tiny">confirmed</span>' : ''}` }, { t: 'Result', f: (i) => (i.result ? `${esc(i.result)}${i.rating ? ` ${'★'.repeat(i.rating)}` : ''}` : '—') },
        { t: 'WhatsApp', f: (i) => `<div class="row nowrap" onclick="event.stopPropagation()">${i.view_status === 'Result pending' ? (i.round === 'client' ? BB.waBtn({ ptype: 'client', pid: i.client_id, ap: i.app_id, iv: i.id, format: 'bbhs_feedback_request' }, 'Client') : BB.waBtn({ ptype: 'user', pid: me.id, ap: i.app_id, iv: i.id, format: 'bbhs_team_task_alert', vars: { task: `Record result of ${i.id}`, record_id: i.id } }, 'Interviewer')) : ['Scheduled', 'Rescheduled'].includes(i.status) ? `${BB.waBtn({ ptype: 'candidate', pid: i.candidate_id, ap: i.app_id, iv: i.id, format: 'bbhs_interview_reminder' }, 'Candidate')}${i.round === 'client' ? BB.waBtn({ ptype: 'client', pid: i.client_id, ap: i.app_id, iv: i.id, format: 'bbhs_interview_reminder' }, 'Client', 'btn sm') : ''}` : ''}</div>` },
        { t: '', f: (i) => (['Scheduled', 'Rescheduled'].includes(i.status) ? `<button class="btn sm primary" data-rec="${i.id}" onclick="event.stopPropagation()">Record result</button>` : '') }], r.rows, { open: (i) => `application:${i.app_id}` })}${BB.pager(r)}</div>`;
